import csv,json,pathlib,collections,hashlib,math
P=pathlib.Path(__file__).parent;raw=P/'PERFORMANCE_STAGE_TIMINGS.csv';rows=list(csv.DictReader(raw.open()));by=collections.defaultdict(list)
for r in rows:by[r['bundle']].append(r)
summary={}
for scope in ['focal','matrix']:
 groups={k:v for k,v in by.items() if v[0]['scope']==scope};totals=[float(v[0]['total_seconds']) for v in groups.values()];st=collections.Counter()
 for v in groups.values():
  for r in v:st[r['stage']]+=float(r['seconds'])
 total=math.fsum(totals);assert math.isclose(math.fsum(st.values()),total,rel_tol=1e-12)
 # Independent raw-cell sum establishes denominator and key-stage numerator.
 chosen=['longevity','primary-analysis'] if scope=='focal' else ['full-matrix']
 direct=math.fsum(float(r['seconds']) for r in rows if r['scope']==scope and r['stage'] in chosen)
 assert math.isclose(direct,sum(st[k] for k in chosen),rel_tol=1e-12)
 summary[scope]={'completed_bundles_with_available_timing':len(groups),'bundles':list(groups),'total_seconds_summed_not_campaign_elapsed':total,'range_minutes':[min(totals)/60,max(totals)/60],'stage_seconds':dict(st),'priority_stage_share_percent':100*direct/total,'per_bundle':{k:{'minutes':float(v[0]['total_seconds'])/60,'priority_share_percent':100*sum(float(r['seconds']) for r in v if r['stage'] in chosen)/float(v[0]['total_seconds'])} for k,v in groups.items()}}
f=summary['focal'];s=f['stage_seconds'];labels=['Longevidad','Análisis primario','Barrido focal','Otros pasos medidos','Tiempo exterior sin asignar'];seconds=[s['longevity'],s['primary-analysis'],s['focal'],sum(v for k,v in s.items() if k not in ['longevity','primary-analysis','focal','unassigned_outer_time']),s['unassigned_outer_time']];assert math.isclose(sum(seconds),f['total_seconds_summed_not_campaign_elapsed'],rel_tol=1e-12)
shares=[100*v/f['total_seconds_summed_not_campaign_elapsed'] for v in seconds]
e={'schema':'mnq_performance_investigation_v1','provenance':{'input_sha256':hashlib.sha256(raw.read_bytes()).hexdigest(),'grain':'one nonoverlapping outer-log stage per completed job, including residual','missing':'MNQ12-25 matrix has no recovered timing-evidence file; focal09-26 still active and excluded','limitations':'stage clocks not CPU profiles; elapsed includes allocation/download/unassigned overhead; different contracts/host contention not paired benchmarks; no RSS evidence available','profile_warnings':'no duplicates or nulls; seconds is not an identifier; actual key is bundle+stage; repeated total_seconds is used once per bundle, never summed per row'},'summary':summary,'comparison_plan':[{'grain':'stage across four completed focal jobs','population':f['bundles'],'unit':'percent of summed observed outer wall seconds','finding':'longevity and primary-analysis dominate measured focal wall time','derivation':'sum(stage seconds)/sum(each job total once)*100','disposition':'chart','reason':'directly identifies acceleration priority without attributing job-runtime differences to code'},{'grain':'four completed matrices with timing','population':summary['matrix']['bundles'],'unit':'percent of summed observed outer wall seconds','finding':'full-matrix is dominant','disposition':'prose','reason':'supporting scope; not a cross-host speedup comparison'}],'chart_values':{'labels':labels,'percent':shares}}
(P/'PERFORMANCE_INVESTIGATION_REPRODUCED.json').write_text(json.dumps(e,indent=2)+'\n')
spec={'version':1,'form':'categorical-bars','title':'Longevidad y análisis primario concentran el tiempo','aside':'Cuatro focales terminados; porcentaje del tiempo total observado','orientation':'horizontal','mode':'grouped','derived':True,'derivationReason':'Suma de segundos de cada etapa dividida por la suma de duración de cada focal, tomada una sola vez','labels':labels,'axis':{'zero':True,'cap':100},'colorMap':dict(zip(labels,['blue','purple','teal','brown','neutral'])),'series':[{'label':'Tiempo observado','valueKind':'percent','role':'subject','data':shares,'derived':True,'derivationReason':'Segundos por etapa / segundos totales × 100'}]}
(P/'PERFORMANCE_CHART_SPEC_REPRODUCED.json').write_text(json.dumps(spec));print(json.dumps({k:{'jobs':v['completed_bundles_with_available_timing'],'priority_share':v['priority_stage_share_percent'],'range_minutes':v['range_minutes']} for k,v in summary.items()}))
